import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;

public class Main {

    public static Response getResponse(String response) {
        return new Response(response);
    }

    public static void main(String[] args) {
        String response = "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\n\r\n<html><body>Hello World!</body></html>";
        Response responseObj = getResponse(response);
        System.out.println("HTTP Status Code: " + responseObj.getStatus());
        System.out.println("Content-Type: " + responseObj.getMediaType());
    }
}

class Request {
    private String request;
    public Request(String request) {
        this.request = request;
    }

    public String getMethod() {
        return request.getMethod();
    }

    public String getURI() {
        return request.getURI();
    }

    public String getPath() {
        return request.getPath();
    }
}

class Response {
    private int statusCode;
    private String statusMessage;
    private Request request;

    public Response(int statusCode, String statusMessage) {
        this.statusCode = statusCode;
        this.statusMessage = statusMessage;
    }

    public int getStatusCode() {
        return statusCode;
    }

    public void setStatusCode(int statusCode) {
        this.statusCode = statusCode;
    }

    public String getStatusMessage() {
        return statusMessage;
    }

    public void setStatusMessage(String statusMessage) {
        this.statusMessage = statusMessage;
    }
}
